class Solution:
    def passwordStrength(self, password: str) -> int:
        seen = set(password)
        ans = 0
        for c in seen:
            if c.islower():
                ans += 1
            elif c.isupper():
                ans += 2
            elif c.isdigit():
                ans += 3
            else:
                ans += 5
        return ans

