class Solution {
public:
    int passwordStrength(string password) {
        unordered_set<char> seen(password.begin(), password.end());
        int ans = 0;
        for (char c : seen) {
            if (islower(c)) ans += 1;
            else if (isupper(c)) ans += 2;
            else if (isdigit(c)) ans += 3;
            else ans += 5;
        }
        return ans;
    }
};

