        bool lower[26] = {}, upper[26] = {}, digit[10] = {}, special[4] = {};
        string sp = "!@#$";
        for (char c : password) {
            if (c >= 'a' && c <= 'z') lower[c - 'a'] = true;
            else if (c >= 'A' && c <= 'Z') upper[c - 'A'] = true;
            else if (c >= '0' && c <= '9') digit[c - '0'] = true;
            else special[sp.find(c)] = true;
        }
        int ans = 0;
        for (bool b : lower) ans += b;
        for (bool b : upper) ans += 2 * b;
        for (bool b : digit) ans += 3 * b;
        for (bool b : special) ans += 5 * b;
        return ans;
    }
};

