class Solution {
    public int passwordStrength(String password) {
        boolean[] lower = new boolean[26], upper = new boolean[26];
        boolean[] digit = new boolean[10], special = new boolean[4];
        String sp = "!@#$";
        for (char c : password.toCharArray()) {
            if (c >= 'a' && c <= 'z') lower[c - 'a'] = true;
            else if (c >= 'A' && c <= 'Z') upper[c - 'A'] = true;
            else if (c >= '0' && c <= '9') digit[c - '0'] = true;
            else special[sp.indexOf(c)] = true;
        }
        int ans = 0;
        for (boolean b : lower) if (b) ans++;
        for (boolean b : upper) if (b) ans += 2;
        for (boolean b : digit) if (b) ans += 3;
        for (boolean b : special) if (b) ans += 5;
        return ans;
    }
}

