var passwordStrength = function(password) {
    const lower = new Array(26).fill(false);
    const upper = new Array(26).fill(false);
    const digit = new Array(10).fill(false);
    const special = new Array(4).fill(false);
    const sp = "!@#$";
    for (const c of password) {
        if (c >= 'a' && c <= 'z') lower[c.charCodeAt(0) - 97] = true;
        else if (c >= 'A' && c <= 'Z') upper[c.charCodeAt(0) - 65] = true;
        else if (c >= '0' && c <= '9') digit[c.charCodeAt(0) - 48] = true;
        else special[sp.indexOf(c)] = true;
    }
    const count = a => a.reduce((s, b) => s + (b ? 1 : 0), 0);
    return count(lower) + 2 * count(upper) + 3 * count(digit) + 5 * count(special);
};
